'use strict';
const $=s=>document.querySelector(s), main=$('#main'), modal=$('#modal');
let saved={};try{saved=JSON.parse(localStorage.getItem('heat-lab-v1')||'{}')||{}}catch{}
let current=Number.isInteger(saved.current)&&saved.current>=0&&saved.current<7?saved.current:0;
let completed=new Set(Array.isArray(saved.completed)?saved.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<7):[]), predictions={},timer=null,playing=false,phase=0,temperature=40,scenario='hot',sorting=false,toolType=0;
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const persist=()=>{try{localStorage.setItem('heat-lab-v1',JSON.stringify({current,completed:[...completed]}))}catch{$('#storage-note').textContent='Progreso disponible solo durante esta sesión.'}};
const svg=(inside)=>`<svg viewBox="0 0 660 260" role="img" aria-label="${LESSONS[current].question}"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#df6b3b" stroke-width="2"/></marker><linearGradient id="water" x2="0" y2="1"><stop stop-color="#92d1d6" stop-opacity=".5"/><stop offset="1" stop-color="#51a7b7" stop-opacity=".8"/></linearGradient></defs>${inside}</svg>`;
const text=(x,y,t,size=16)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}">${t}</text>`;
const cup=(x,y,hot=true)=>`<g transform="translate(${x} ${y})"><ellipse cx="0" cy="95" rx="84" ry="9" fill="#ccd7c8"/><path d="M49 2h20c42 0 42 57 0 57H55" fill="none" stroke="${hot?'#d77a52':'#70aabd'}" stroke-width="14"/><path d="M-60 0H60L51 75Q0 100-51 75Z" fill="${hot?'#e99b70':'url(#water)'}" stroke="${hot?'#b96a44':'#5194a4'}" stroke-width="2"/><ellipse cy="0" rx="60" ry="12" fill="${hot?'#6b493b':'#b8e4e7'}"/>${hot?'<g class="steam" stroke="#a6afa0" stroke-width="4" fill="none"><path d="M-25-23q-12-13 0-26t0-26M0-23q-12-13 0-26t0-26M25-23q-12-13 0-26t0-26"/></g>':'<g fill="#efffff" stroke="#93c3cf"><rect x="-36" y="3" width="22" height="22" rx="4" transform="rotate(-12)"/><rect x="8" y="9" width="25" height="25" rx="4" transform="rotate(10)"/></g>'}</g>`;
function stop(){clearInterval(timer);timer=null;playing=false;$('#stage')?.classList.add('paused')}
function map(){ $('#map').innerHTML=LESSONS.map((l,i)=>`<button class="mission ${current===i?'active':''} ${completed.has(i)?'done':''}" data-mission="${i}" ${current===i?'aria-current="step"':''}><span>${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.short}</button>`).join('');$('#progress').value=completed.size;$('#progress-label').textContent=`${completed.size} de 7 completadas`;document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>render(+b.dataset.mission,true))}
function openModal(title,body){$('#modal-body').innerHTML=`<h2>${title}</h2>${body}`;modal.showModal()}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function render(i,focus=false){stop();current=i;phase=0;temperature=40;scenario='hot';toolType=0;persist();map();const l=LESSONS[i];main.innerHTML=`<div class="topline"><span class="eyebrow">MISIÓN ${String(i+1).padStart(2,'0')} / 07</span><span class="badge">EXPERIMENTA · DESCUBRE · COMPRENDE</span></div><h1>${l.title}</h1><p class="intro">${l.intro}</p><div class="prediction"><span>Antes de probar, ¿qué crees?</span>${l.prediction.map((p,j)=>`<button data-prediction="${j}">${p}</button>`).join('')}<p class="prediction-response" aria-live="polite"></p></div><section class="experiment" aria-label="Experimento interactivo"><div class="lab-head"><span><i class="live-dot"></i> MESA DE EXPERIMENTOS</span><span>0${i+1} — OBSERVA QUÉ CAMBIA</span></div><div class="stage" id="stage"></div><div class="controls" id="controls"></div><p class="model-note" id="model-note"></p></section><div class="below"><section class="explanation"><span class="eyebrow">LA IDEA QUE TE LLEVAS</span><h3 style="margin-top:10px">${l.question}</h3><p>${l.explain}</p><details><summary>Un poco más de ciencia</summary><p>${l.detail}</p></details><button class="text-button" id="glossary">Abrir diccionario de ciencia ↗</button><button class="curiosity" id="curiosity"><span>✦ SIGUE TU CURIOSIDAD</span>${l.curiosity} ↗</button></section><section class="challenge"><span class="eyebrow">PONLO A PRUEBA</span><h3 style="margin-top:10px">Un pequeño reto</h3><p>${l.challenge}</p><div class="answers">${l.answers.map((a,j)=>`<button class="answer" data-answer="${j}">${a}</button>`).join('')}</div><button class="text-button" id="hint">Necesito una pista</button><p class="feedback" id="feedback" aria-live="polite"></p></section></div><div class="navigation"><button class="outline" id="prev" ${i===0?'disabled':''}>← Anterior</button><span>La curiosidad no tiene prisa.</span><button class="primary" id="next">${i===6?'Ir al reto final':'Siguiente misión'} →</button></div>`;
document.querySelectorAll('[data-prediction]').forEach(b=>b.onclick=()=>{predictions[i]=+b.dataset.prediction;document.querySelectorAll('[data-prediction]').forEach(x=>x.classList.toggle('selected',x===b));$('.prediction-response').textContent='Predicción registrada. Prueba el experimento y compárala con lo que observas.'});
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const right=+b.dataset.answer===l.answer;b.classList.add(right?'correct':'wrong');$('#feedback').textContent=right?`¡Lo descubriste! ${l.why}`:`Vuelve a observar. ${l.hint} Puedes intentarlo otra vez.`;if(right){completed.add(i);persist();map()}});$('#hint').onclick=()=>$('#feedback').textContent=l.hint;$('#curiosity').onclick=()=>openModal(l.curiosity,`<p>${l.curious}</p><p><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">Explorar en PhET ↗</a> — cambia los materiales y observa la energía.</p>`);$('#glossary').onclick=()=>openModal('Palabras para explorar','<p><b>Partícula:</b> una parte diminuta de la materia, como un átomo o una molécula.</p><p><b>Energía cinética:</b> energía asociada al movimiento.</p><p><b>Promedio:</b> suma de varios valores dividida entre cuántos hay.</p><p><b>Equilibrio térmico:</b> estado en que dos cuerpos tienen la misma temperatura y no intercambian calor neto.</p><p><b>Gradiente:</b> cómo cambia una cantidad, aquí la temperatura, con la posición.</p><p><b>Aislante térmico:</b> material que dificulta transferir calor.</p><p><b>Magnitud escalar:</b> cantidad descrita con un valor y una unidad, sin dirección.</p>');$('#prev').onclick=()=>render(i-1,true);$('#next').onclick=()=>i===6?finalQuiz():render(i+1,true);setupExperiment();if(focus)main.focus();}
function motionControls(extra=''){return `${extra}<button id="play">${reduced?'Avanzar una etapa':'▶ Iniciar'}</button><button id="step" class="outline">Una etapa →</button><button id="restart" class="outline">↺ Reiniciar</button>`}
function bindMotion(draw,max=20){$('#play').onclick=()=>{if(reduced){phase=Math.min(max,phase+1);draw();return}if(playing){stop();$('#play').textContent='▶ Continuar';$('#stage').classList.add('paused')}else{playing=true;$('#play').textContent='Ⅱ Pausar';$('#stage').classList.remove('paused');timer=setInterval(()=>{phase=Math.min(max,phase+(current===1?.12:1));draw();if(phase>=max){stop();$('#play').textContent='Completado'}},current===1?40:350)}};$('#step').onclick=()=>{stop();phase=Math.min(max,phase+1);draw();$('#play').textContent=reduced?'Avanzar una etapa':'▶ Continuar'};$('#restart').onclick=()=>{stop();phase=0;draw();$('#play').textContent=reduced?'Avanzar una etapa':'▶ Iniciar'};draw();$('#stage').classList.add('paused')}
function setupExperiment(){const controls=$('#controls'),stage=$('#stage'),note=$('#model-note');
if(current===0){controls.innerHTML=motionControls('<button id="scenario" class="outline">Cambiar a vaso con hielo</button>');note.textContent='Modelo de la dirección del calor. Los valores son ejemplos; no toques líquidos calientes.';const draw=()=>{let hot=scenario==='hot',x1=hot?245:405,x2=hot?395:255;stage.innerHTML=svg(cup(145,105,hot)+`<g transform="translate(490 115)"><path d="M-35 65L-59 34q-10-14 2-20 8-4 17 10l7 10V-22q0-12 10-12t10 12v40h5v-51q0-12 10-12t10 12v51h5v-43q0-12 10-12t10 12v43h5V-8q0-12 10-12t10 12v66q0 47-52 47-35 0-49-40Z" fill="#efbe9a" stroke="#ae846b" stroke-width="2"/></g>${phase?`<path class="flow" d="M${x1} 135H${x2}" stroke="#df6b3b" stroke-width="5" marker-end="url(#arrow)"/>`:''}${text(145,245,hot?'Taza · 65 °C':'Vaso con hielo · 5 °C',14)}${text(495,245,'Mano · 32 °C',14)}${text(330,83,phase?'ENERGÍA EN TRÁNSITO':'¿HACIA DÓNDE IRÁ?',11)}`);};bindMotion(draw,1);$('#scenario').onclick=()=>{stop();scenario=scenario==='hot'?'cold':'hot';phase=0;$('#scenario').textContent=scenario==='hot'?'Cambiar a vaso con hielo':'Cambiar a taza caliente';$('#play').textContent='▶ Observar';draw()}}
if(current===1){controls.innerHTML=motionControls('<label>Temperatura <input id="temp" type="range" min="0" max="100" value="40"><output id="temp-value">40 °C</output></label>');note.textContent='Modelo cualitativo de un gas. Las partículas no aumentan de tamaño. Usa «Una etapa» para ver posiciones sin animación.';const draw=()=>{const dots=Array.from({length:30},(_,j)=>{const speed=(.4+j%5*.15)*(1+temperature/50),x=130+((j*67+phase*speed*14)%400),y=55+((j*41+phase*speed*9)%130);return `<circle cx="${x}" cy="${y}" r="6" fill="${temperature>55?'#df7950':'#4b9eaf'}"/>`}).join('');stage.innerHTML=svg(`<rect x="100" y="30" width="460" height="175" rx="25" fill="#ffffff99" stroke="#a7b7aa" stroke-width="2"/>${dots}${text(330,240,`${temperature} °C · ${temperature>65?'Mayor':temperature<25?'Menor':'Intermedia'} agitación`,16)}`)};bindMotion(draw,100000);$('#temp').oninput=e=>{temperature=+e.target.value;$('#temp-value').textContent=temperature+' °C';draw()}}
if(current===2){controls.innerHTML=motionControls('<label>Bloque A <input id="block-temp" type="range" min="20" max="100" value="80"><output id="block-value">80 °C</output></label>');temperature=80;note.textContent='Igual material y capacidad térmica, sin pérdidas. Etapas ilustrativas: no representan segundos.';const draw=()=>{let mean=(temperature+20)/2,diff=(temperature-20)/2*(1-phase/20),a=mean+diff,b=mean-diff;stage.innerHTML=svg(`<rect x="110" y="65" width="160" height="130" rx="12" fill="${phase===20?'#aeaaa1':'#e99b70'}"/><path d="M270 65l23-18v130l-23 18" fill="#ba7658"/><rect x="390" y="65" width="160" height="130" rx="12" fill="${phase===20?'#aeaaa1':'#86c0cc'}"/><path d="M550 65l23-18v130l-23 18" fill="#5b939e"/>${phase>0&&phase<20&&temperature>20?'<path class="flow" d="M299 130h70" stroke="#df6b3b" stroke-width="5" marker-end="url(#arrow)"/>':''}${text(190,140,a.toFixed(1)+' °C',27)}${text(470,140,b.toFixed(1)+' °C',27)}${text(330,235,phase===20||temperature===20?'Equilibrio: misma temperatura':phase?'A cede energía · B recibe energía':'Une los bloques para observar',15)}`)};bindMotion(draw);$('#block-temp').oninput=e=>{stop();phase=0;temperature=+e.target.value;$('#block-value').textContent=temperature+' °C';$('#play').textContent='▶ Unir bloques';draw()}}
if(current===3){controls.innerHTML='<div class="conversion"><label>Energía <input id="energy" type="number" min="0" max="1000000" step="any" value="1"></label><label>Unidad <select id="unit"><option value="cal">cal</option><option value="kcal">kcal</option><option value="J">J</option></select></label><button id="cal-info">Explorar calorímetro ↗</button></div>';note.textContent='Conversión del libro: 1 cal ≈ 4.187 J. Son unidades de energía, no de temperatura.';stage.innerHTML=svg(`<path d="M215 60v135q115 50 230 0V60" fill="#bdd0bf" stroke="#557f78" stroke-width="5"/><path d="M240 85v99q90 30 180 0V85" fill="url(#water)" stroke="#557f78" stroke-width="2"/><ellipse cx="330" cy="60" rx="115" ry="24" fill="#d9e1d5" stroke="#557f78" stroke-width="3"/><rect x="310" y="12" width="16" height="143" rx="7" fill="white" stroke="#456768" stroke-width="3"/><rect x="315" y="55" width="6" height="96" rx="3" fill="#e77a45"/><path d="M375 24v111l20 12" fill="none" stroke="#557f78" stroke-width="6"/>${text(330,249,'CALORÍMETRO',12)}`)+'<div id="conversion-result" class="readout" aria-live="polite"></div>';const convert=()=>{let raw=$('#energy').value,n=Number(raw),u=$('#unit').value;if(raw===''||!Number.isFinite(n)||n<0||n>1000000){$('#conversion-result').textContent='Escribe un número entre 0 y 1 000 000.';return}let cal=u==='J'?n/4.187:u==='kcal'?n*1000:n;const fmt=v=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:4}).format(v);$('#conversion-result').textContent=`${fmt(cal)} cal = ${fmt(cal/1000)} kcal ≈ ${fmt(cal*4.187)} J`};$('#energy').oninput=convert;$('#unit').onchange=convert;convert();$('#cal-info').onclick=()=>openModal('Dentro de un calorímetro','<p><b>Recipiente aislante:</b> reduce el intercambio con el exterior.</p><p><b>Termómetro:</b> registra cambios de temperatura.</p><p><b>Agitador:</b> ayuda a distribuir la temperatura.</p><p>Con la cantidad de materia, sus propiedades y el cambio de temperatura se determina la energía intercambiada.</p><p><b>Ejemplo:</b> 2 kcal × 1 000 = 2 000 cal. Después: 2 000 × 4.187 = 8 374 J.</p>')}
if(current===4){controls.innerHTML=motionControls();note.textContent='Modelo comparativo de enfriamiento hacia 20 °C. Etapas sin duración real; el aislamiento reduce las pérdidas.';const draw=()=>{let a=20+60*Math.exp(-phase*.15),b=20+60*Math.exp(-phase*.035);stage.innerHTML=svg(cup(170,85,true)+cup(485,85,true)+`<path d="M420 90v86q65 45 130 0V90" fill="none" stroke="#739075" stroke-width="14" stroke-dasharray="8 3"/>${text(170,230,`Sin aislamiento · ${a.toFixed(1)} °C`,15)}${text(485,230,`Con aislamiento · ${b.toFixed(1)} °C`,15)}${text(330,24,'AMBIENTE · 20 °C',11)}`)};bindMotion(draw,40)}
if(current===5){controls.innerHTML=['Clínico digital','Líquido en tubo','Sonda industrial'].map((t,j)=>`<button class="outline" data-tool="${j}">${t}</button>`).join('')+'<button id="sensor-info">¿Qué cambia aquí? ↗</button>';note.textContent='Ilustraciones de instrumentos: el tipo y rango adecuados dependen del uso y del fabricante.';const draw=()=>{const titles=['Clínico digital · temperatura corporal','Líquido en tubo · cambio de volumen','Sonda industrial · respuesta eléctrica'];stage.innerHTML=svg(toolType===1?`<rect x="305" y="20" width="45" height="170" rx="20" fill="white" stroke="#7b9290" stroke-width="3"/><circle cx="327" cy="190" r="26" fill="#e87b4d"/><rect x="320" y="80" width="14" height="110" fill="#e87b4d"/>${Array.from({length:7},(_,j)=>`<path d="M337 ${40+j*20}h20" stroke="#56736f"/>`).join('')}${text(330,250,titles[toolType],15)}`:`<g transform="rotate(-12 330 120)"><rect x="175" y="65" width="285" height="105" rx="${toolType===0?40:12}" fill="#f9f9ef" stroke="#73908a" stroke-width="3"/><rect x="230" y="88" width="135" height="57" rx="6" fill="#c1d1ae"/>${text(298,126,toolType===0?'36.5 °C':'80.0 °C',25)}<circle cx="408" cy="118" r="15" fill="#e77a45"/><path d="M175 117H90" stroke="#74929b" stroke-width="${toolType===0?15:5}" stroke-linecap="round"/></g>${text(330,245,titles[toolType],15)}`);document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.tool===toolType)))};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{toolType=+b.dataset.tool;draw()});$('#sensor-info').onclick=()=>openModal('Una propiedad que podemos medir',`<p>${['Un sensor cambia su respuesta eléctrica según la temperatura. El dispositivo convierte esa señal en un número en pantalla.','El líquido se dilata al aumentar su temperatura: ocupa más volumen y sube por el tubo.','La sonda emplea una propiedad eléctrica que cambia con la temperatura. Está diseñada para un rango y unas condiciones particulares.'][toolType]}</p><p>Otros termómetros aprovechan cambios de color o la deformación de materiales.</p>`);draw()}
if(current===6){controls.innerHTML='<label>Cuerpo <select id="pan-body"><option>Cobre</option><option>Acero</option></select></label><label>Mango <select id="pan-handle"><option>Madera</option><option>Cobre</option></select></label><button id="heat-pan">Calentar modelo</button><button id="materials" class="outline">Comparar 8 materiales ↗</button>';note.textContent='Modelo cualitativo. Los materiales y el diseño de utensilios reales requieren otras consideraciones.';const draw=(heat=false)=>{let wood=$('#pan-handle').value==='Madera';stage.innerHTML=svg(`<ellipse cx="275" cy="185" rx="115" ry="15" fill="#c9d3c3"/><path d="M160 100q115 35 230 0l-25 65q-90 45-180 0Z" fill="${$('#pan-body').value==='Cobre'?'#cb9066':'#9da6a1'}" stroke="#755b4d" stroke-width="3"/><ellipse cx="275" cy="100" rx="115" ry="30" fill="#e3baa0" stroke="#755b4d" stroke-width="3"/><path d="M385 118h125" stroke="${wood?'#967350':heat?'#df663e':'#ba8a64'}" stroke-width="24" stroke-linecap="round"/>${heat?'<path class="flow" d="M245 225v-33M275 225v-33M305 225v-33" stroke="#df6b3b" stroke-width="4" marker-end="url(#arrow)"/>':''}${text(330,40,heat?(wood?'El mango de madera dificulta el paso del calor':'El cobre también conduce calor hacia el mango'):'Elige tus materiales y prueba',14)}`)};$('#pan-body').onchange=()=>draw();$('#pan-handle').onchange=()=>draw();$('#heat-pan').onclick=()=>draw(true);$('#materials').onclick=materialsModal;draw()}}
function materialsModal(){const rows=sorting?[...MATERIALS].sort((a,b)=>b[2]-a[2]):MATERIALS;openModal('¿Qué material conduce más?',`<p>Valores de las páginas del libro, en <b>W/(m·K)</b>. Son orientativos: cambian según composición y condiciones. Las barras usan el punto medio de cada rango y escala lineal.</p><div class="table-wrap"><table><thead><tr><th>Material</th><th><button id="sort-materials">Conductividad ${sorting?'↓':'↕'}</button></th><th>Comparación</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${m[0]}</td><td>${m[1]}</td><td><div class="bar" style="width:${m[2]/378.65*100}%"></div></td></tr>`).join('')}</tbody></table></div><p>El cobre facilita transferir calor; el corcho dificulta esa transferencia. El mercurio figura como dato del libro, no como material para experimentar en casa.</p>`);$('#sort-materials').onclick=()=>{sorting=!sorting;modal.close();materialsModal()}}
function finalQuiz(){stop();main.innerHTML=`<div class="eyebrow">LA ÚLTIMA MISIÓN</div><h1>Piensa como un científico<span style="color:var(--orange)">.</span></h1><p class="intro">Cinco situaciones nuevas. Sin reloj, sin penalizaciones. Puedes volver a las misiones cuando quieras.</p>${FINAL_QUIZ.map((q,i)=>`<section class="final-card"><h3>${i+1}. ${q[0]}</h3><div class="answers">${q[1].map((a,j)=>`<button class="answer" data-final="${i}" data-choice="${j}">${a}</button>`).join('')}</div><p class="feedback" id="final-feedback-${i}" aria-live="polite"></p></section>`).join('')}<p id="final-result" aria-live="polite"></p><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">Explora energía y materiales en PhET ↗</a><a target="_blank" rel="noopener noreferrer" href="https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry">Profundiza con OpenStax (en inglés) ↗</a></div><button id="back-missions" class="outline">← Volver a las misiones</button>`;const correct=new Set();document.querySelectorAll('[data-final]').forEach(b=>b.onclick=()=>{const i=+b.dataset.final,q=FINAL_QUIZ[i],ok=+b.dataset.choice===q[2];b.classList.add(ok?'correct':'wrong');$(`#final-feedback-${i}`).textContent=ok?`Exacto. ${q[3]}`:`Piensa de nuevo: ${q[3]} Inténtalo otra vez.`;if(ok)correct.add(i);$('#final-result').textContent=correct.size===5?'¡Resolviste los cinco casos! Ahora puedes explicar cómo viaja la energía.':`${correct.size} de 5 situaciones resueltas.`});$('#back-missions').onclick=()=>render(current,true);main.focus()}
$('#library').onclick=()=>openModal('Tu cuaderno del calor',`${LESSONS.map((l,i)=>`<section><h3>${i+1}. ${l.title}</h3><p>${l.explain}</p><p>${l.detail}</p></section>`).join('')}<h3>Conductividad: valores del libro</h3><table><thead><tr><th>Material</th><th>W/(m·K)</th></tr></thead><tbody>${MATERIALS.map(m=>`<tr><td>${m[0]}</td><td>${m[1]}</td></tr>`).join('')}</tbody></table><p>Valores orientativos, dependientes de las condiciones. Se normaliza la escritura de las unidades.</p><h3>Fuentes y exploración</h3><p>Fuente principal: imagen proporcionada de la lectura 15, «El calor, la temperatura y la energía cinética», Conexiones Física 2.º, páginas 68–69. Adaptación educativa con ilustraciones originales.</p><p><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">PhET: Formas y cambios de energía ↗</a>. Experimenta con materiales y observa los cambios de energía.</p><p><a target="_blank" rel="noopener noreferrer" href="https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry">OpenStax: transferencia de calor y calorimetría (inglés) ↗</a>. Referencia para profundizar acompañado de un adulto.</p>`);
$('#final-link').onclick=finalQuiz;$('.brand').onclick=e=>{e.preventDefault();render(0,true)};$('#reset-progress').onclick=()=>openModal('¿Reiniciar tu expedición?','<p>Se borrarán las misiones completadas en este navegador.</p><button id="confirm-reset">Sí, reiniciar progreso</button>');modal.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){completed.clear();predictions={};modal.close();render(0,true)}});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{reduced=e.matches;render(current)});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();const b=$('#play');if(b)b.textContent=reduced?'Avanzar una etapa':'▶ Continuar'}});render(current);

const labObserver=new MutationObserver(()=>{const figure=$('#stage svg');if(figure){const labels=[...figure.querySelectorAll('text')].map(t=>t.textContent).join('. ');figure.setAttribute('aria-label',LESSONS[current].question+'. '+labels)}});labObserver.observe(main,{childList:true,subtree:true});
